#include <iostream>
#include <fstream>
#include <cstring>
#include <cstdio>      // remove(), rename()
using namespace std;

struct Student {
    int  roll;
    char name[30];
    float marks;
};

void addStudents() {
    ofstream fout("students.dat", ios::binary | ios::app);
    Student s;
    char more = 'y';
    while (more == 'y' || more == 'Y') {
        cout << "Roll: ";  cin >> s.roll;
        cout << "Name: ";  cin.ignore(); cin.getline(s.name, 30);
        cout << "Marks: "; cin >> s.marks;
        fout.write((char*)&s, sizeof(s));
        cout << "Add more? (y/n): "; cin >> more;
    }
    fout.close();
}

void showAll() {
    ifstream fin("students.dat", ios::binary);
    if (!fin) { cout << "No data file yet" << endl; return; }
    Student s;
    cout << "Roll\tName\t\tMarks" << endl;
    while (fin.read((char*)&s, sizeof(s))) {
        cout << s.roll << "\t" << s.name << "\t\t" << s.marks << endl;
    }
    fin.close();
}

void search(int r) {
    ifstream fin("students.dat", ios::binary);
    Student s;
    bool found = false;
    while (fin.read((char*)&s, sizeof(s))) {
        if (s.roll == r) {
            cout << "Found: " << s.name << ", " << s.marks << endl;
            found = true;
            break;
        }
    }
    if (!found) cout << "Roll " << r << " not found" << endl;
}

void updateMarks(int r, float newMarks) {
    fstream f("students.dat", ios::in | ios::out | ios::binary);
    Student s;
    while (f.read((char*)&s, sizeof(s))) {
        if (s.roll == r) {
            s.marks = newMarks;
            long pos = (long)f.tellg() - (long)sizeof(s);  // start of this record
            f.seekp(pos);
            f.write((char*)&s, sizeof(s));
            cout << "Record updated" << endl;
            return;
        }
    }
    cout << "Roll not found" << endl;
}

void deleteRecord(int r) {
    ifstream fin("students.dat", ios::binary);
    ofstream temp("temp.dat", ios::binary);
    Student s;
    bool found = false;
    while (fin.read((char*)&s, sizeof(s))) {
        if (s.roll == r) found = true;          // skip this one
        else temp.write((char*)&s, sizeof(s));
    }
    fin.close();
    temp.close();
    remove("students.dat");
    rename("temp.dat", "students.dat");
    cout << (found ? "Record deleted" : "Roll not found") << endl;
}

void showRecord(int n) {                 // n = 1 for the first record
    ifstream fin("students.dat", ios::binary);
    Student s;
    fin.seekg((n - 1) * sizeof(s), ios::beg);
    if (fin.read((char*)&s, sizeof(s)))
        cout << s.roll << " " << s.name << " " << s.marks << endl;
    else
        cout << "Record " << n << " does not exist" << endl;
}

