#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
using namespace std;

int main() {
    ifstream fin("story.txt");
    if (!fin) { cout << "File not found" << endl; return 1; }
    string line, word;
    int lines = 0, words = 0, chars = 0;
    while (getline(fin, line)) {
        lines++;
        chars += line.length();
        stringstream ss(line);          // split the line into words
        while (ss >> word) words++;
    }
    cout << "Lines: " << lines << "\nWords: " << words
         << "\nCharacters (without newlines): " << chars << endl;
    return 0;
}

ifstream fin("story.txt");
string w;
int count = 0;
while (fin >> w) {
    for (char &c : w) c = tolower(c);                 // "The" -> "the"
    if (!w.empty() && ispunct(w.back())) w.pop_back(); // remove . , ! at end
    if (w == "the") count++;
}
cout << "'the' appears " << count << " times" << endl;

