#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
using namespace std;

int main() {
    ifstream fin("marks.csv");
    string line, roll, name, marksStr;
    getline(fin, line);                         // skip the header line
    string topName; int top = -1, total = 0, n = 0;
    while (getline(fin, line)) {
        stringstream ss(line);
        getline(ss, roll, ',');
        getline(ss, name, ',');
        getline(ss, marksStr, ',');
        int m = stoi(marksStr);
        total += m; n++;
        if (m > top) { top = m; topName = name; }
    }
    cout << "Topper: " << topName << " (" << top << ")" << endl;
    cout << "Class average: " << (double)total / n << endl;
    return 0;
}

