#include <iostream>
#include <fstream>
#include <stdexcept>
using namespace std;

string firstLine(const string& fileName) {
    ifstream fin(fileName);
    if (!fin) throw runtime_error("Cannot open " + fileName);
    string line;
    if (!getline(fin, line)) throw runtime_error(fileName + " is empty");
    return line;
}

int main() {
    try {
        cout << firstLine("school.txt") << endl;
        cout << firstLine("missing.txt") << endl;
    }
    catch (const runtime_error& e) {
        cout << "File error: " << e.what() << endl;
    }
    return 0;
}

